22	/**
23	 * The `AGENTS.md` content (consumer usage guide).
24	 *
25	 * @example Serve the guide from an app route
26	 * ```ts
27	 * import { AGENTS_MD } from "@pantoken/ai";
28	 *
29	 * export function GET() {
30	 *   return new Response(AGENTS_MD, { headers: { "Content-Type": "text/markdown" } });
31	 * }
32	 * ```
33	 */
34	export const AGENTS_MD: string = ASSETS.agents;
35	/**
36	 * The `llms.txt` content.
37	 *
38	 * @example Write it to disk yourself
39	 * ```ts
40	 * import { writeFileSync } from "node:fs";
41	 * import { LLMS_TXT } from "@pantoken/ai";
42	 *
43	 * writeFileSync("llms.txt", LLMS_TXT);
44	 * ```
45	 */
46	export const LLMS_TXT: string = ASSETS.llms;
47	
48	/** An agent/editor tool pantoken can install assets for. */
49	export type AgentTool = "agents" | "llms" | "cursor" | "copilot" | "windsurf" | "claude";
50	
51	interface AssetTarget {
52	  file: string;
53	  content: string;
54	}
55	
56	/** Where each tool's asset(s) are written, relative to the target directory. */
57	const TARGETS: Record<AgentTool, AssetTarget[]> = {
58	  agents: [{ file: "AGENTS.md", content: ASSETS.agents }],
59	  llms: [{ file: "llms.txt", content: ASSETS.llms }],
60	  cursor: [{ file: ".cursor/rules/pantoken.mdc", content: ASSETS.cursor }],
61	  copilot: [{ file: ".github/copilot-instructions.md", content: ASSETS.copilot }],
62	  windsurf: [{ file: ".windsurf/rules/pantoken.md", content: ASSETS.windsurf }],
63	  claude: [
64	    { file: ".claude/skills/init-pantoken/SKILL.md", content: ASSETS.initSkill },
65	    { file: ".claude/skills/scaffold-pantoken/SKILL.md", content: ASSETS.scaffoldSkill },
66	    { file: "AGENTS.md", content: ASSETS.agents },
67	  ],
68	};
69	
70	/**
71	 * Every installable tool key.
72	 *
73	 * @example Install each tool individually
74	 * ```ts
75	 * import { AGENT_TOOLS, installAgentAssets } from "@pantoken/ai";
76	 *
77	 * for (const tool of AGENT_TOOLS) installAgentAssets(tool, "./my-app");
78	 * ```
79	 */
80	export const AGENT_TOOLS: readonly AgentTool[] = Object.keys(TARGETS) as AgentTool[];
81	
82	const AGENT_TOOL_SET = new Set<string>(AGENT_TOOLS);
83	
84	function ensureAgentTool(tool: string): asserts tool is AgentTool {
85	  if (AGENT_TOOL_SET.has(tool)) return;
86	  throw new Error(`Unknown tool "${tool}". Expected one of: ${AGENT_TOOLS.join(", ")}.`);
87	}
88	
89	/**
90	 * Write pantoken's agent assets for a tool into a consumer repo.
91	 *
92	 * @param tool - A specific {@link AgentTool}, or `"all"` for every asset.
93	 * @param dir - The target directory (default `"."`).
94	 * @returns The paths written.
95	 *
96	 * @example Install one tool's assets into a repo
97	 * ```ts
98	 * import { installAgentAssets } from "@pantoken/ai";
99	 *
100	 * const written = installAgentAssets("cursor", "./my-app");
101	 * // → ["my-app/.cursor/rules/pantoken.mdc"]
102	 * ```
103	 *
104	 * @example Install every asset into the current directory
105	 * ```ts
106	 * import { installAgentAssets } from "@pantoken/ai";
107	 *
108	 * installAgentAssets("all");
109	 * // writes AGENTS.md, llms.txt, and the Cursor/Copilot/Windsurf/Claude assets
110	 * ```
111	 */
112	export function installAgentAssets(tool: AgentTool | "all", dir = "."): string[] {
113	  const tools =
114	    tool === "all" ? AGENT_TOOLS : ((ensureAgentTool(tool), [tool]) as readonly AgentTool[]);
115	  const written = new Set<string>();
116	  for (const t of tools) {
117	    for (const { file, content } of TARGETS[t]) {
118	      const path = join(dir, file);
119	      mkdirSync(dirname(path), { recursive: true });
120	      writeFileSync(path, content);
121	      written.add(path);
122	    }
123	  }
124	  return [...written];
125	}
126	
127	/**
128	 * Scaffold a starter project for a platform (via `@pantoken/scaffold`), and install pantoken's
129	 * agent assets (via {@link installAgentAssets}) into the same directory.
130	 *
131	 * @param platform - A {@link ScaffoldPlatform}.
132	 * @param dir - The target directory (default `"."`). Its basename (or `"pantoken-app"` for `"."`)
133	 *   is substituted for `{{projectName}}` in the scaffold's template files.
134	 * @param tool - Which agent tool's assets to install alongside the scaffold (default `"all"`).
135	 * @returns The paths written, scaffold files first.
136	 *
137	 * @example Scaffold a React starter with every agent asset installed
138	 * ```ts
139	 * import { scaffoldAndInit } from "@pantoken/ai";
140	 *
141	 * scaffoldAndInit("react", "./my-app");
142	 * ```
143	 */
144	export async function scaffoldAndInit(
145	  platform: string,
146	  dir = ".",
147	  tool: AgentTool | "all" = "all",
148	): Promise<string[]> {
149	  const scaffoldPaths = await scaffoldProject(platform, dir);
150	  const assetPaths = installAgentAssets(tool, dir);
151	  return [...scaffoldPaths, ...assetPaths];
152	}
