1	/**
2	 * Copy the committed demo snippets (`docs/demos/*.html`) into `public/demos/` so the `/play` runner can
3	 * fetch them. They're bare markup fragments (no `<link>` of their own — the runner injects the shared
4	 * sheets), so this is a plain file copy.
5	 *
6	 * Runs in `docs:assets` (via `demos.ts`) and again on edits during `docs:dev` (the config's workspace
7	 * orchestrator invokes this as the `@pantoken/docs#demo-snippets` node, watching `docs/demos`). Writing
8	 * into `public/` triggers a Vite full reload, so an open `/play` demo refetches the updated snippet.
9	 *
10	 * @module
11	 */
12	import { copyFileSync, existsSync, mkdirSync, readdirSync } from "node:fs";
13	import { join } from "node:path";
14	
15	const docsRoot = join(import.meta.dirname, "..");
16	const demosSrc = join(docsRoot, "demos");
17	const demosOut = join(docsRoot, "public", "demos");
18	
19	/** Copy every `docs/demos/*.html` into `public/demos/`. Returns the number of snippets staged. */
20	export function stageDemoSnippets(): number {
21	  mkdirSync(demosOut, { recursive: true });
22	  if (!existsSync(demosSrc)) return 0;
23	  let count = 0;
24	  for (const file of readdirSync(demosSrc)) {
25	    if (!file.endsWith(".html")) continue;
26	    copyFileSync(join(demosSrc, file), join(demosOut, file));
27	    count += 1;
28	  }
29	  return count;
30	}
31	
32	// Run when invoked directly (`node scripts/stage-demo-snippets.ts`) — the docs:dev watch path. When
33	// imported by `demos.ts`, only the export is used.
34	if (import.meta.url === `file://${process.argv[1]}`) {
35	  const count = stageDemoSnippets();
36	  console.log(`✓ demo-snippets: staged ${String(count)} demo(s) to public/demos/`);
37	}
