25	/**
26	 * Thrown for user-facing CLI errors (e.g., missing platform under --yes);
27	 * carries an exit code for process.exit or CommanderError handling.
28	 */
29	export class ScaffoldCliError extends Error {
30	  constructor(
31	    message: string,
32	    public readonly exitCode = 1,
33	  ) {
34	    super(message);
35	    this.name = "ScaffoldCliError";
36	  }
37	}
