39	/**
40	 * Whether a value should be interactively prompted for:
41	 * no value given, not --yes, and (optionally injected) TTY check passes.
42	 *
43	 * @param value - The provided value (or undefined)
44	 * @param opts - Options: `yes` flag forces non-interactive, `isTTY` injectable for testing
45	 * @returns True if interactive prompt should proceed
46	 */
47	export function shouldPrompt(
48	  value: string | undefined,
49	  opts: { yes?: boolean; isTTY?: boolean },
50	): boolean {
51	  if (value) return false; // Already provided
52	  if (opts.yes) return false; // --yes forces non-interactive
53	  // Check TTY status; default to process.stdin.isTTY
54	  const isTTY = opts.isTTY ?? process.stdin?.isTTY ?? false;
55	  return isTTY;
56	}
