58	export interface ResolveScaffoldTargetOptions {
59	  platformArg?: string;
60	  dirOption?: string;
61	  yes?: boolean;
62	  isTTY?: boolean; // injectable for tests; defaults to process.stdin.isTTY
63	  t: LocaleLookup["t"];
64	}
