75	 * @throws ScaffoldCliError when required values are missing non-interactively
76	 */
77	export async function resolveScaffoldTarget(
78	  options: ResolveScaffoldTargetOptions,
79	): Promise<{ platform: string; dir: string }> {
80	  const { platformArg, dirOption, yes, t } = options;
81	  const isTTY = options.isTTY ?? process.stdin?.isTTY ?? false;
82	
83	  // Resolve platform
84	  let platform = platformArg ?? "";
85	  if (!platform) {
86	    if (!shouldPrompt(platform, { yes, isTTY })) {
