88	        t("errorMissingPlatform", { platforms: SCAFFOLD_PLATFORMS.join(", ") }),
89	      );
90	    }
91	
92	    // Prompt for platform
93	    const result = await select({
94	      message: t("promptPlatform"),
95	      options: SCAFFOLD_PLATFORMS.map((p) => ({ value: p, label: p })),
96	    });
97	
98	    if (isCancel(result)) {
99	      cancel(t("cancelled"));
100	      throw new ScaffoldCliError(t("cancelled"), 1);
101	    }
102	
103	    platform = result as string;
104	  }
105	
106	  // Validate the platform
107	  if (!checkScaffoldPlatform(platform)) {
