3	export interface CommandCycleOption {
4	  id: string;
5	  label: string;
6	  launcher: string;
7	  color: string;
8	  darkColor?: string;
9	  icon?: string;
10	}
11	
12	export interface CommandCycleTimings {
13	  typeMs: number;
14	  deleteMs: number;
15	  holdMs: number;
16	  startHoldMs: number;
17	  blinkMs: number;
18	}
19	
20	type CyclePhase = "idle" | "typing" | "paused" | "deleting";
21	
22	export interface UseCommandCycleOptions {
23	  options: CommandCycleOption[];
24	  suffix: string | ComputedRef<string>;
25	  isPaused: Ref<boolean>;
26	  reducedMotion: Ref<boolean>;
27	  timings: CommandCycleTimings;
28	}
29	
30	export interface CommandCycleController {
31	  activeIndex: Ref<number>;
32	  activeOption: ComputedRef<CommandCycleOption>;
33	  iconVisible: ComputedRef<boolean>;
34	  typedLauncher: ComputedRef<string>;
35	  typedSuffix: ComputedRef<string>;
36	  visibleText: ComputedRef<string>;
37	  cursorBlink: Ref<boolean>;
38	  totalLength: ComputedRef<number>;
39	  start: () => void;
40	  stop: () => void;
41	  pauseAtFull: () => void;
42	  resume: () => void;
43	  pick: (index: number) => void;
44	}
45	
46	export function useCommandCycle({
47	  options,
48	  suffix,
49	  isPaused,
50	  reducedMotion,
51	  timings,
52	}: UseCommandCycleOptions) {
53	  const activeIndex = ref(0);
54	  const activeOption = computed(() => options[activeIndex.value]);
55	
56	  const phase = ref<CyclePhase>("typing");
57	  const charCount = ref(0);
58	  const cursorBlink = ref(false);
59	
60	  let timeoutId: ReturnType<typeof setTimeout> | undefined;
61	  let blinkTimeoutId: ReturnType<typeof setTimeout> | undefined;
62	
63	  const suffixValue = computed(() => (typeof suffix === "string" ? suffix : suffix.value));
64	  const iconOffset = computed(() => (activeOption.value.icon ? 1 : 0));
65	  const iconVisible = computed(() => !!activeOption.value.icon && charCount.value > 0);
66	
67	  const typedLauncher = computed(() =>
68	    activeOption.value.launcher.slice(
69	      0,
70	      Math.min(Math.max(0, charCount.value - iconOffset.value), activeOption.value.launcher.length),
71	    ),
72	  );
73	
74	  const typedSuffix = computed(() =>
75	    suffixValue.value.slice(
76	      0,
77	      Math.max(0, charCount.value - iconOffset.value - activeOption.value.launcher.length),
78	    ),
79	  );
80	
81	  const visibleText = computed(() => `${typedLauncher.value}${typedSuffix.value}`);
82	  const totalLength = computed(
83	    () => iconOffset.value + activeOption.value.launcher.length + suffixValue.value.length,
84	  );
85	
86	  function clearTimers() {
87	    clearTimeout(timeoutId);
88	    clearTimeout(blinkTimeoutId);
89	  }
90	
91	  function beatBlink() {
92	    cursorBlink.value = false;
93	    clearTimeout(blinkTimeoutId);
94	    requestAnimationFrame(() => {
95	      cursorBlink.value = true;
96	      blinkTimeoutId = setTimeout(() => {
97	        cursorBlink.value = false;
98	      }, timings.blinkMs);
99	    });
100	  }
101	
102	  function scheduleNext() {
103	    clearTimeout(timeoutId);
104	    if (isPaused.value || reducedMotion.value) return;
105	
106	    if (phase.value === "idle") {
107	      timeoutId = setTimeout(() => {
108	        activeIndex.value = (activeIndex.value + 1) % options.length;
109	        phase.value = "typing";
110	        scheduleNext();
111	      }, timings.startHoldMs);
112	      return;
113	    }
114	
115	    if (phase.value === "typing") {
116	      if (charCount.value < totalLength.value) {
117	        timeoutId = setTimeout(() => {
118	          charCount.value++;
119	          scheduleNext();
120	        }, timings.typeMs);
121	      } else {
122	        phase.value = "paused";
123	        beatBlink();
124	        scheduleNext();
125	      }
126	      return;
127	    }
128	
129	    if (phase.value === "paused") {
130	      timeoutId = setTimeout(() => {
131	        phase.value = "deleting";
132	        scheduleNext();
133	      }, timings.holdMs);
134	      return;
135	    }
136	
137	    if (charCount.value > 0) {
138	      timeoutId = setTimeout(() => {
139	        charCount.value--;
140	        scheduleNext();
141	      }, timings.deleteMs);
142	    } else {
143	      phase.value = "idle";
144	      beatBlink();
145	      scheduleNext();
146	    }
147	  }
148	
149	  function start() {
150	    if (reducedMotion.value) {
151	      charCount.value = totalLength.value;
152	      return;
153	    }
154	    scheduleNext();
155	  }
156	
157	  function stop() {
158	    clearTimers();
159	  }
160	
161	  function pauseAtFull() {
162	    clearTimers();
163	    cursorBlink.value = false;
164	    charCount.value = totalLength.value;
165	    phase.value = "paused";
166	  }
167	
168	  function resume() {
169	    scheduleNext();
170	  }
171	
172	  function pick(index: number) {
173	    activeIndex.value = index;
174	    pauseAtFull();
175	    if (!isPaused.value) scheduleNext();
176	  }
177	
178	  const controller: CommandCycleController = {
179	    activeIndex,
180	    activeOption,
181	    iconVisible,
182	    typedLauncher,
183	    typedSuffix,
184	    visibleText,
185	    cursorBlink,
186	    totalLength,
187	    start,
188	    stop,
189	    pauseAtFull,
190	    resume,
191	    pick,
192	  };
193	
194	  return controller;
195	}
