15	const assets: Record<string, string> = {
16	  agents: read("assets/AGENTS.md"),
17	  llms: read("assets/llms.txt"),
18	  cursor: `${read("assets/cursor.mdc").trimEnd()}\n\n${copilot}`,
19	  copilot,
20	  windsurf: read("assets/windsurf.md"),
21	  initSkill: read("skills/init-pantoken/SKILL.md"),
22	  scaffoldSkill: read("skills/scaffold-pantoken/SKILL.md"),
23	};
24	
25	const outDir = join(root, "generated");
26	mkdirSync(outDir, { recursive: true });
27	writeFileSync(
28	  join(outDir, "assets.ts"),
29	  `// GENERATED by scripts/generate.ts — do not edit by hand.\nexport const ASSETS: Record<string, string> = ${JSON.stringify(assets, null, 2)};\n`,
30	);
31	console.log(`✓ inlined ${Object.keys(assets).length} agent assets`);
32	
33	// Generate locale bundles from i18n-cache
34	import { readdirSync } from "node:fs";
35	const i18nCacheDir = join(root, "i18n-cache");
36	const localesDir = join(outDir, "locales");
37	mkdirSync(localesDir, { recursive: true });
38	
39	const localeMap: Record<string, string> = {};
40	try {
41	  const cacheFiles = readdirSync(i18nCacheDir);
42	  for (const file of cacheFiles) {
43	    if (!file.endsWith(".json")) continue;
44	    const locale = file.slice(0, -".json".length);
45	    const cachePath = join(i18nCacheDir, file);
46	    const bundle = JSON.parse(readFileSync(cachePath, "utf8"));
47	
48	    // Generate a TypeScript file for this locale
49	    const tsContent = `// GENERATED by scripts/generate.ts — do not edit by hand.\nexport const LOCALE_${locale.toUpperCase()} = ${JSON.stringify(
50	      bundle,
51	      null,
52	      2,
53	    )} as const;\n`;
54	    writeFileSync(join(localesDir, `${locale}.ts`), tsContent);
55	    localeMap[locale] = `LOCALE_${locale.toUpperCase()}`;
56	  }
57	} catch {
58	  // i18n-cache directory doesn't exist yet, that's okay
59	}
60	
61	// Generate the index that exports all locales
62	const indexContent = `// GENERATED by scripts/generate.ts — do not edit by hand.
63	${Object.entries(localeMap)
64	  .map(([locale, varName]) => `import { ${varName} } from "./${locale}.js";`)
65	  .join("\n")}
66	
67	export const LOCALES: Record<string, Record<string, string>> = {
68	${Object.entries(localeMap)
69	  .map(([locale, varName]) => `  ${locale}: ${varName},`)
70	  .join("\n")}
71	};
72	`;
73	writeFileSync(join(localesDir, "index.ts"), indexContent);
74	if (Object.keys(localeMap).length > 0) {
75	  console.log(`✓ generated locale bundles for: ${Object.keys(localeMap).join(", ")}`);
