  "$schema": "https://raw.githubusercontent.com/fallow-rs/fallow/main/schema.json",

  "workspaces": {
    "patterns": [
      "docs",
      "packages/*",
      "formats/*",
      "platforms/*",
      "renderers/*",
      "bundlers/*",
      "design/*",
      "ai/*",
      "plugins/pantoken",
      "plugins/pantoken/*",
      "plugins/postcss/*",
      "plugins/typedoc/*",
      "plugins/vite/*",
      "tools/*"
