18	const sharedCssdocTemplate = JSON.stringify(JSON.parse(stripJsoncComments(cssdocJsonc)), null, 2);
19	
20	// Every template's entry markup is patterned off `@pantoken/plugin-layouts`'s `wrapper` app-shell
21	// layout via these tokens, so editing that layout's cssdoc regenerates every platform's markup.
22	const rootClassName = wrapperRootClassName();
23	function substituteWrapperTokens(content: string): string {
