1	/**
2	 * Shared primitives for the docs and i18n translation pipelines.
3	 *
4	 * Both pipelines shell out to an AI CLI that reads a prompt via stdin and writes a response to
5	 * stdout. This module owns the spawn mechanism, JSON response parser, and the content-addressed
6	 * translation-memory core so neither pipeline has to duplicate them.
7	 *
8	 * @module
9	 */
10	import { createHash } from "node:crypto";
11	import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
12	import { dirname } from "node:path";
13	import { spawn } from "node:child_process";
