15	/**
16	 * Pull the first `{…}` JSON object out of a model response, tolerating surrounding prose or code
17	 * fences. Returns `null` when no valid object is found.
18	 */
19	export function extractJsonObject(raw: string): Record<string, unknown> | null {
20	  const start = raw.indexOf("{");
21	  const end = raw.lastIndexOf("}");
22	  if (start === -1 || end <= start) return null;
23	  try {
24	    const parsed = JSON.parse(raw.slice(start, end + 1)) as unknown;
25	    return typeof parsed === "object" && parsed !== null
26	      ? (parsed as Record<string, unknown>)
27	      : null;
28	  } catch {
29	    return null;
30	  }
31	}
32	
33	/**
34	 * Spawn an AI command, send `prompt` via stdin, and resolve with the trimmed stdout.
35	 *
36	 * The caller is responsible for building `args` — the convention is that `-p` is always the final
37	 * arg so the `agy-wrapper.sh` can strip it and forward the prompt via agy's own `-p` flag.
38	 *
39	 * @param command - The executable (e.g. `"claude"` or a path to `agy-wrapper.sh`).
40	 * @param args    - Extra flags plus the terminal `-p` sentinel (e.g. `["--model", "x", "-p"]`).
41	 * @param prompt  - The prompt text; written to the child's stdin then the pipe is closed.
42	 * @param context - Optional label for the error message (e.g. `"locale 'hu'"` or `"foo.md"`).
43	 */
44	export function spawnPrompt(
45	  command: string,
46	  args: string[],
47	  prompt: string,
48	  context?: string,
49	): Promise<string> {
50	  return new Promise((resolve, reject) => {
51	    const child = spawn(command, args, { stdio: ["pipe", "pipe", "pipe"] });
52	    let out = "";
53	    let err = "";
54	    child.stdout.setEncoding("utf8");
55	    child.stderr.setEncoding("utf8");
56	    child.stdout.on("data", (chunk: string) => {
57	      out += chunk;
58	    });
59	    child.stderr.on("data", (chunk: string) => {
60	      err += chunk;
61	    });
62	    // Cast to a minimal shape: ChildProcessByStdio omits .on() in @types/node ≥ 22.
63	    const proc = child as unknown as {
64	      on(event: "error", listener: (e: Error) => void): void;
65	      on(event: "close", listener: (code: number | null) => void): void;
66	    };
67	    proc.on("error", reject);
68	    proc.on("close", (code) => {
69	      if (code !== 0) {
70	        const where = context ? ` for ${context}` : "";
71	        reject(new Error(`AI command exited ${String(code)}${where}: ${err.trim()}`));
72	      } else {
73	        resolve(out.trimEnd());
74	      }
75	    });
76	    child.stdin.end(prompt);
77	  });
78	}
