80	// ── Translation memory ────────────────────────────────────────────────────────
81	
82	interface CacheFile {
83	  version: 1;
84	  entries: Record<string, string>;
85	}
86	
87	/**
88	 * Content-addressed translation cache backed by a committed JSON file.
89	 *
90	 * Pipeline-specific facades (docs, i18n) wrap this with their own key-construction logic and
91	 * factory method — neither `get` nor `set` here computes a key; callers pass pre-computed hashes.
92	 *
93	 * Set `prune: true` (docs) to discard entries not touched this session on `save()` — keeps the
94	 * cache from accumulating stale keys after source content is deleted. Leave it off (i18n) to
95	 * preserve all entries across runs.
96	 */
97	export class TranslationMemory {
98	  readonly path: string;
99	  private readonly _entries: Map<string, string>;
100	  private readonly _prune: boolean;
101	  private readonly _used = new Set<string>();
102	  hits = 0;
103	
104	  private constructor(path: string, entries: Map<string, string>, prune: boolean) {
105	    this.path = path;
106	    this._entries = entries;
107	    this._prune = prune;
108	  }
109	
110	  /** Open (or create) a memory backed by `path`. */
111	  static open(path: string, options?: { prune?: boolean }): TranslationMemory {
112	    if (!existsSync(path)) return new TranslationMemory(path, new Map(), options?.prune ?? false);
113	    const parsed = JSON.parse(readFileSync(path, "utf8")) as CacheFile;
114	    return new TranslationMemory(
115	      path,
116	      new Map(Object.entries(parsed.entries ?? {})),
117	      options?.prune ?? false,
118	    );
119	  }
120	
121	  /** Return a cached value and record a hit; returns `undefined` on a miss. */
122	  get(key: string): string | undefined {
123	    const val = this._entries.get(key);
124	    if (val !== undefined) {
125	      this._used.add(key);
126	      this.hits++;
127	    }
128	    return val;
129	  }
130	
131	  /** Store a translated value and mark the key as used. */
132	  set(key: string, value: string): void {
133	    this._entries.set(key, value);
134	    this._used.add(key);
135	  }
136	
137	  /** True when the key is present (no counter side-effects). */
138	  has(key: string): boolean {
139	    return this._entries.has(key);
140	  }
141	
142	  /** Iterate all stored keys. */
143	  keys(): IterableIterator<string> {
144	    return this._entries.keys();
145	  }
146	
147	  /** Write entries to disk, optionally pruning to only the keys touched this session. */
148	  save(): void {
149	    const source = this._prune ? [...this._used].sort() : [...this._entries.keys()].sort();
150	    const out: Record<string, string> = {};
151	    for (const key of source) {
152	      const val = this._entries.get(key);
153	      if (val !== undefined) out[key] = val;
154	    }
155	    mkdirSync(dirname(this.path), { recursive: true });
156	    writeFileSync(this.path, `${JSON.stringify({ version: 1, entries: out }, null, 2)}\n`);
157	  }
158	}
