// ── Locale bundle codegen ──────────────────────────────────────────────────────

/**
 * Generate one `LOCALE_<CODE>.ts` module per `<code>.json` file in `i18nCacheDir`, plus an
 * `index.ts` importing and re-exporting them all as `LOCALES`, into `localesDir`.
 *
 * Shared by `ai/pantoken-ai/scripts/generate.ts` and `packages/scaffold/scripts/generate.ts`, whose
 * CLI i18n setups both bake a translated `i18n-cache/` into a generated locale bundle the same way.
 * Silently produces an empty `LOCALES` map when `i18nCacheDir` doesn't exist yet (no cache built).
 *
 * @param i18nCacheDir - Directory of `<locale>.json` translation-cache files.
 * @param localesDir - Output directory for the generated `<locale>.ts` files and `index.ts`.
 * @returns The locale codes a bundle was generated for.
 */
export function generateLocaleBundles(i18nCacheDir: string, localesDir: string): string[] {
  mkdirSync(localesDir, { recursive: true });

  const localeMap: Record<string, string> = {};
  try {
    const cacheFiles = readdirSync(i18nCacheDir);
    for (const file of cacheFiles) {
      if (!file.endsWith(".json")) continue;
      const locale = file.slice(0, -".json".length);
      const cachePath = join(i18nCacheDir, file);
      const bundle = JSON.parse(readFileSync(cachePath, "utf8"));

      const tsContent = `// GENERATED by scripts/generate.ts — do not edit by hand.\nexport const LOCALE_${locale.toUpperCase()} = ${JSON.stringify(
        bundle,
        null,
        2,
      )} as const;\n`;
      writeFileSync(join(localesDir, `${locale}.ts`), tsContent);
      localeMap[locale] = `LOCALE_${locale.toUpperCase()}`;
    }
  } catch {
    // i18n-cache directory doesn't exist yet, that's okay
  }

  const indexContent = `// GENERATED by scripts/generate.ts — do not edit by hand.
${Object.entries(localeMap)
  .map(([locale, varName]) => `import { ${varName} } from "./${locale}.js";`)
  .join("\n")}

export const LOCALES: Record<string, Record<string, string>> = {
${Object.entries(localeMap)
  .map(([locale, varName]) => `  ${locale}: ${varName},`)
  .join("\n")}
};
`;
  writeFileSync(join(localesDir, "index.ts"), indexContent);

  return Object.keys(localeMap);
}

