const outer = document.querySelector('.gs-agent-terminal');
const inner = document.querySelector('.gs-agent__input-wrap');
outer.dispatchEvent(new MouseEvent('mouseenter', {bubbles:false}));
inner.dispatchEvent(new MouseEvent('mouseenter', {bubbles:false}));
await new Promise(r => setTimeout(r, 50));
const buttons = [...document.querySelectorAll('.gs-command-row__popover button')].map(b => b.textContent.trim());
JSON.stringify({buttons})

const btn = [...document.querySelectorAll('.gs-command-row__popover button')].find(b => b.textContent.trim() === 'cursor');
btn.click();
await new Promise(r => setTimeout(r, 50));
const row = document.querySelector('.gs-agent__input-wrap .gs-command-row');
JSON.stringify({text: row.textContent.trim(), html: row.innerHTML.slice(0, 400)})

async function pick(label) {
  const outer = document.querySelector('.gs-agent-terminal');
  const inner = document.querySelector('.gs-agent__input-wrap');
  outer.dispatchEvent(new MouseEvent('mouseenter', {bubbles:false}));
  inner.dispatchEvent(new MouseEvent('mouseenter', {bubbles:false}));
  await new Promise(r => setTimeout(r, 30));
  const btn = [...document.querySelectorAll('.gs-command-row__popover button')].find(b => b.textContent.trim() === label);
  btn.click();
  await new Promise(r => setTimeout(r, 30));
  const row = document.querySelector('.gs-agent__input-wrap .gs-command-row');
  const iconEl = row.querySelector('.gs-command-row__icon');
  return { label, launcherText: row.querySelector('span').nextSibling?.textContent, icon: iconEl ? iconEl.className : null, full: row.childNodes[row.childNodes.length>2?2:1]?.textContent };
}
const results = [];
for (const l of ['codex','copilot','q','gemini','claude']) results.push(await pick(l));
JSON.stringify(results, null, 1)

const row = document.querySelector('.gs-agent__input-wrap .gs-command-row');
const icon = row.querySelector('.gs-command-row__icon');
JSON.stringify({text: row.textContent.replace(/claude|gemini|cursor|codex|copilot|q$/g,'').trim(), hasIcon: !!icon})

const outer = document.querySelector('.gs-agent-terminal');
const inner = document.querySelector('.gs-agent__input-wrap');
outer.dispatchEvent(new MouseEvent('mouseenter', {bubbles:false}));
inner.dispatchEvent(new MouseEvent('mouseenter', {bubbles:false}));
await new Promise(r => setTimeout(r, 30));
const btn = [...document.querySelectorAll('.gs-command-row__popover button')].find(b => b.textContent.trim() === 'q');
btn.click();
await new Promise(r => setTimeout(r, 30));
const row = document.querySelector('.gs-agent__input-wrap .gs-command-row');
const icon = row.querySelector('.gs-command-row__icon');
JSON.stringify({rowText: row.textContent, hasIcon: !!icon})

const row = document.querySelector('.gs-agent__input-wrap .gs-command-row');
const firstChild = row.firstElementChild;
JSON.stringify({firstChildClass: firstChild.className, firstChildText: firstChild.textContent})

document.querySelector('.gs-agent-terminal').dispatchEvent(new MouseEvent('mouseleave', {bubbles:false}));
document.querySelector('button[aria-label="Terminal mode"]').click();
await new Promise(r => setTimeout(r, 100));
JSON.stringify({activeSurface: document.querySelector('.gs-started__stage').className})

