1	<script setup lang="ts">
2	import { computed, nextTick, onUnmounted, ref } from "vue";
3	import type { CommandCycleController, CommandCycleOption } from "./useCommandCycle";
4	
5	interface Props {
6	  cycle: CommandCycleController;
7	  options: CommandCycleOption[];
8	  copyLabel: string;
9	  copiedLabel: string;
10	  suffixVariant: "terminal" | "agent";
11	  showCopy?: boolean;
12	  showSelector?: boolean;
13	  copyVisible?: boolean;
14	  popoverVisible?: boolean;
15	  autoOpenOnRowHover?: boolean;
16	  popoverPlacement?: "below" | "above";
17	}
18	
19	const props = withDefaults(defineProps<Props>(), {
20	  showCopy: true,
21	  showSelector: true,
22	  autoOpenOnRowHover: true,
23	  popoverPlacement: "below",
24	});
25	
26	const popoverOpen = ref(false);
27	const copyFeedback = ref(false);
28	const copyButtonRef = ref<HTMLButtonElement | null>(null);
29	let copyFeedbackTimeoutId: ReturnType<typeof setTimeout> | undefined;
30	const resolvedPopoverOpen = computed(() => {
31	  if (props.popoverVisible === undefined) return popoverOpen.value;
32	  return props.popoverVisible || popoverOpen.value;
33	});
34	
35	onUnmounted(() => {
36	  clearTimeout(copyFeedbackTimeoutId);
37	});
38	
39	function closePopoverUnless(e: FocusEvent, container: HTMLElement | null) {
40	  const next = e.relatedTarget as Node | null;
41	  if (!container || !next || !container.contains(next)) popoverOpen.value = false;
42	}
43	
44	async function pickOption(index: number, event: MouseEvent) {
45	  props.cycle.pick(index);
46	  popoverOpen.value = false;
47	
48	  // Keyboard activation of a menu button dispatches click with detail=0.
49	  if (!props.showCopy || event.detail !== 0) return;
50	  await nextTick();
51	  copyButtonRef.value?.focus({ preventScroll: true });
52	}
53	
54	function tone(option: CommandCycleOption): string {
55	  return option.darkColor ? `light-dark(${option.color}, ${option.darkColor})` : option.color;
56	}
57	
58	async function copyText(value: string, onSuccess: () => void) {
59	  if (!value) return;
60	
61	  try {
62	    if (navigator.clipboard?.writeText) {
63	      await navigator.clipboard.writeText(value);
64	    } else {
65	      const probe = document.createElement("textarea");
66	      probe.value = value;
67	      probe.setAttribute("readonly", "true");
68	      probe.style.position = "fixed";
69	      probe.style.opacity = "0";
70	      document.body.appendChild(probe);
71	      probe.select();
72	      document.execCommand("copy");
73	      document.body.removeChild(probe);
74	    }
75	
76	    onSuccess();
77	  } catch {
78	    // Ignore clipboard failures in restricted contexts.
79	  }
80	}
81	
82	async function copyVisibleCommand() {
83	  await copyText(props.cycle.visibleText.value, () => {
84	    copyFeedback.value = true;
85	    clearTimeout(copyFeedbackTimeoutId);
86	    copyFeedbackTimeoutId = setTimeout(() => {
87	      copyFeedback.value = false;
88	    }, 1400);
89	  });
90	}
91	
92	function openPopoverIfEnabled() {
93	  if (props.showSelector && props.autoOpenOnRowHover) popoverOpen.value = true;
94	}
95	</script>
96	
97	<template>
98	  <span
99	    class="gs-command-row"
100	    tabindex="0"
101	    @mouseenter="openPopoverIfEnabled"
102	    @focus="props.showSelector ? (popoverOpen = true) : undefined"
103	    @focusout="
104	      closePopoverUnless($event, ($event.currentTarget as HTMLElement)?.parentElement ?? null)
105	    "
106	  >
107	    <slot
108	      name="leading"
109	      :cycle="props.cycle"
110	      :active-option="props.cycle.activeOption.value"
111	    ></slot>
112	    <span
113	      v-if="props.cycle.iconVisible.value"
114	      class="instui-icon gs-command-row__icon"
115	      :class="`-icon-${props.cycle.activeOption.value.icon}`"
116	      :style="{ color: tone(props.cycle.activeOption.value) }"
117	      aria-hidden="true"
118	    ></span>
119	    <span :style="{ color: tone(props.cycle.activeOption.value) }">{{
120	      props.cycle.typedLauncher.value
121	    }}</span>
122	    <span class="gs-command-row__suffix" :class="`-${props.suffixVariant}`">{{
123	      props.cycle.typedSuffix.value
124	    }}</span>
125	    <span
126	      class="gs-command-row__cursor"
127	      :class="{ 'gs-command-row__cursor--blink': props.cycle.cursorBlink.value }"
128	      :style="{ backgroundColor: tone(props.cycle.activeOption.value) }"
129	      aria-hidden="true"
130	    ></span>
131	    <slot name="inline" :cycle="props.cycle" :active-option="props.cycle.activeOption.value"></slot>
132	    <button
133	      v-if="props.showCopy"
134	      ref="copyButtonRef"
135	      type="button"
136	      class="gs-command-row__copy"
137	      :class="{ '-copied': copyFeedback, '-visible': props.copyVisible }"
138	      :aria-label="props.copyLabel"
139	      @click="copyVisibleCommand"
140	    >
141	      <span class="instui-icon -icon-copy" aria-hidden="true"></span>
142	    </button>
143	    <span
144	      v-if="props.showCopy && copyFeedback"
145	      class="gs-command-row__copy-popover"
146	      aria-live="polite"
147	      >{{ props.copiedLabel }}</span
148	    >
149	    <span
150	      v-if="props.showSelector && resolvedPopoverOpen"
151	      class="gs-command-row__popover"
152	      :class="`-${props.popoverPlacement}`"
153	      @mouseleave="popoverOpen = false"
154	    >
155	      <button
156	        v-for="(option, i) in props.options"
157	        :key="option.id"
158	        type="button"
159	        :style="{ color: tone(option) }"
160	        @click="pickOption(i, $event)"
161	      >
162	        <span
163	          v-if="option.icon"
164	          class="instui-icon gs-command-row__icon"
165	          :class="`-icon-${option.icon}`"
166	          aria-hidden="true"
167	        ></span>
168	        {{ option.label }}
169	      </button>
170	    </span>
171	    <slot
172	      name="trailing"
173	      :cycle="props.cycle"
174	      :active-option="props.cycle.activeOption.value"
175	    ></slot>
176	  </span>
